Ext.define('BNK.view.common.EdocButtonContainerViewController', {
    extend: 'Ext.app.ViewController',
    alias: 'controller.common.edocbuttoncontainer',

    config: {
        viewId: 'EdocButtonContainer'
    },

    /* [결재선] 버튼 */
    onClickApprovalLine: function(button, e, eOpts) {
        var me = this.getView().up('window'),
            win = Ext.create('BNK.view.common.ApprovalLinePopup', {});

        me.mon(win, 'selected', function(records, popup) {
            popup.close();	// 팝업창 닫기

            var me = this,
                vm = me.getViewModel(),
                refs = me.getReferences(),
                approvalLineGrid = refs.approvalLineGrid;	// 결재선

                // 결재선설정
                ApprovalBoxSvc.setApprovalLine({
                    scope               : me,
                    command             : vm.get('command'), 		// 결재선구분자 : 기안/담당자기안
                    approvalLineGrid    : approvalLineGrid,			// 결재선 그리드 객체
                    approvalLineRecords : records					// 결재선선택 데이터
                });
        }, me);

        //win.getElementConfig().setStyle('z-index', '90000'); // 결재선 팝업창이 멘위로 안올라오는 문제가 있어 방어코드 추가함

        win.show();
    },

    /* [기안] 버튼 */
    onClickDraft: function(button, e, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            view = me.getView().up('window'),
            ctrl = view.controller,
            total = vm.get('total'), // 전체 건수, 전체 금액
            docData = vm.get('records');

        ctrl.onClickDraft();
    },

    /* [결재] 버튼 */
    onClickSanction: function(button, e, eOpts) {
        var me = this,
            view = me.getView().up('window'),
            ctrl = view.controller;

        ctrl.onClickSanction();
    },

    /* [반송] 버튼 */
    onClickSendBack: function(button, e, eOpts) {
        var me = this,
            view = me.getView().up('window'),
            ctrl = view.controller;

        ctrl.onClickSendBack();
    },

    /* [회수] 버튼 */
    onClickWithdrawal: function(button, e, eOpts) {
        var me = this,
            view = me.getView().up('window'),
            ctrl = view.controller;

        ctrl.onClickWithdrawal();
    },

    /* [닫기] 버튼 */
    onClose: function(button, e, eOpts) {
        var me = this,
            view = me.getView().up('window');
        view.close();
    }

});